/* Pure matching functions, shared by the UI and regression tests. */
const Kitchen = (() => {
  const aliases = {'egg':'eggs','tomato':'tomatoes','potato':'potatoes','onions':'onion','brocolli':'broccoli','brocoli':'broccoli','scallion':'spring onion','scallions':'spring onion','green onion':'spring onion','green onions':'spring onion','garlic cloves':'garlic','olive oil':'oil','vegetable oil':'oil','cooking oil':'oil','black pepper':'pepper','mushroom':'mushrooms','cucumbers':'cucumber','minced beef':'ground beef','beef mince':'ground beef','minced pork':'ground pork','pork mince':'ground pork','minced chicken':'ground chicken','chicken mince':'ground chicken','minced meat':'unspecified ground meat','ground meat':'unspecified ground meat','mince':'unspecified ground meat','rice':'unspecified rice','white rice':'unspecified rice','raw rice':'uncooked rice','dry rice':'uncooked rice','leftover rice':'cooked rice','chilled rice':'cooked rice','repolyo':'cabbage','sayote':'chayote','talong':'eggplant','aubergine':'eggplant','aubergines':'eggplant','carrot':'carrots','green bean':'green beans','string beans':'green beans','canned chickpeas':'cooked chickpeas','canned lentils':'cooked lentils','canned white beans':'cooked white beans','cooked munggo':'cooked mung beans','oats':'rolled oats','bananas':'banana','pasta':'dry pasta'};
  const normalize = s => {const key=String(s).trim().toLowerCase().replace(/\s+/g,' ');return aliases[key]||key;};
  const units={g:['mass',1],kg:['mass',1000],oz:['mass',28.349523125],lb:['mass',453.59237],ml:['volume',1],l:['volume',1000],cup:['volume',240],tbsp:['volume',15],tsp:['volume',5],piece:['piece',1],slice:['slice',1],clove:['clove',1]};
  function convert(q,from,to){if(!units[from]||!units[to]||units[from][0]!==units[to][0])return null;return q*units[from][1]/units[to][1];}
  function assess(items,pantry,scale=1){return items.map(item=>{const required=item.quantity*scale,stock=pantry[item.id];if(!stock)return {...item,required,status:'missing',shortage:required};if(stock.quantity===null||stock.quantity===''||!Number.isFinite(Number(stock.quantity))||Number(stock.quantity)<0)return {...item,required,status:'unknown'};const amount=convert(Number(stock.quantity),stock.unit,item.unit);if(amount===null)return {...item,required,status:'unknown'};return {...item,required,available:amount,status:amount+1e-6>=required?'enough':'short',shortage:Math.max(0,required-amount)};});}
  function status(checks){return checks.some(i=>i.status==='missing'||i.status==='short')?'needs':checks.some(i=>i.status==='unknown')?'quantities':'ready';}
  function combine(recipes,servings){const map=new Map();for(const r of recipes)for(const i of r.items){const amount=i.quantity*servings/r.servings;if(map.has(i.id)){const row=map.get(i.id);const converted=convert(amount,i.unit,row.unit);if(converted===null)throw Error('Incompatible recipe units: '+i.id);row.quantity+=converted;}else map.set(i.id,{...i,quantity:amount});}return [...map.values()];}
  const label = id => ({'unspecified rice':'Rice — choose cooked or uncooked','unspecified ground meat':'Minced meat — choose a type','dry pasta':'Pasta (dry)','cooked chickpeas':'Chickpeas (cooked / canned, drained)','cooked lentils':'Lentils (cooked, drained)','cooked white beans':'White beans (cooked / canned, drained)','cooked mung beans':'Mung beans (cooked)','canned sardines':'Sardines (canned, drained)','canned tuna':'Tuna (canned, drained)','ground beef':'Minced beef','ground pork':'Minced pork','chicken thigh':'Chicken thigh (boneless)','chicken breast':'Chicken breast (boneless)','oil':'Cooking oil'}[id]||id);
  function format(q,unit,system='metric'){let u=unit,n=q;if(system==='us'&&unit==='g'){n=q/28.349523125;u='oz';}if(system==='us'&&unit==='ml'){n=q/15;u='tbsp';}const digits=n<1?2:1;return `${Number(n.toFixed(digits))} ${u}`;}
  return {normalize,units,convert,assess,status,combine,label,format};
})();
if(typeof module!=='undefined')module.exports=Kitchen;
